"""Original PatchProof maintenance fixture. SPDX-License-Identifier: CC0-1.0."""

from copy import deepcopy


def _deletion(value):
    return type(value) is dict and set(value) == {"$delete"} and value["$delete"] is True


def _same(left, right):
    if type(left) is not type(right):
        return False
    if type(left) is dict:
        return set(left) == set(right) and all(_same(left[key], right[key]) for key in left)
    if type(left) is list:
        return len(left) == len(right) and all(_same(a, b) for a, b in zip(left, right))
    return left == right


def _validate(value, path=(), patch=False):
    if type(value) is dict:
        if patch and _deletion(value):
            return
        for key, child in value.items():
            if type(key) is not str or not key or "." in key or key.startswith("$"):
                raise ValueError("configuration keys must be nonempty simple names")
            _validate(child, path + (key,), patch)
    elif type(value) is list:
        for child in value:
            _validate(child, path, False)
    elif value is not None and type(value) not in (str, int, bool):
        raise ValueError("unsupported configuration value")


def _overlay(base, patch):
    result = deepcopy(base)
    for key, incoming in patch.items():
        if incoming is None or _deletion(incoming):
            result.pop(key, None)
        elif type(incoming) is dict:
            previous = result.get(key)
            result[key] = _overlay(previous if type(previous) is dict else {}, incoming)
        elif type(incoming) is list:
            result[key] = deepcopy(result.get(key, [])) + deepcopy(incoming) if type(result.get(key)) is list else deepcopy(incoming)
        else:
            result[key] = incoming
    return result


def _changes(before, after, prefix=()):
    changed = []
    for key in sorted(set(before) | set(after)):
        path = prefix + (key,)
        if key not in before or key not in after:
            changed.append(".".join(path))
            continue
        left, right = before[key], after[key]
        if type(left) is dict and type(right) is dict:
            if left != right:
                changed.append(".".join(path))
        elif not _same(left, right):
            changed.append(".".join(path))
    return sorted(changed)


def merge_config(base, layers):
    """Apply ordered overlays and report paths changed from the original."""
    if type(base) is not dict or type(layers) is not list:
        raise ValueError("expected a base object and a list of overlays")
    _validate(base)
    for layer in layers:
        if type(layer) is not dict or _deletion(layer):
            raise ValueError("every overlay must be an object, not a root deletion marker")
        _validate(layer, patch=True)
    merged = deepcopy(base)
    for layer in layers:
        merged = _overlay(merged, layer)
    changed = _changes(base, merged)
    return {"config": merged, "changed": changed}
